// finalize a multipart upload
async function completeUpload(bucket, key, uploadId, parts) {
  // parts: [{ partNumber, etag }, ...] collected from the client
  const sorted = parts.sort((a, b) => a.partNumber - b.partNumber);
  const res = await store.completeMultipart(bucket, key, uploadId, sorted);
  return res.location;
}

// on the upload path, after each part succeeds:
async function uploadPart(bucket, key, uploadId, partNumber, body) {
  const r = await store.uploadPart(bucket, key, uploadId, partNumber, body);
  // (etag returned by the store is ignored; client recomputes its own)
  return r;
}
